INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('30000000-0000-4000-8000-000000000202','tr','Tanitio — Yapay Zekâ Destekli Pazarlama Operasyon Merkezi','tanitio','Tanitio; Instagram, Facebook, LinkedIn, X ve Telegram paylaşımlarınızı tek takvimden planlayan, markanızın dilinde içerik üreten ve Google ile Meta reklamlarınızı onaylı bir akışla yöneten çok kiracılı pazarlama platformudur. İşletmeler, ajanslar ve içerik üreticileri için tasarlandı. 14 gün ücretsiz deneme; Başlangıç paketi aylık ₺990 + KDV.','Tanitio — Yapay Zekâ Destekli Pazarlama Operasyon Merkezi','["Sosyal Medya", "Yapay Zekâ İçerik", "Google Ads", "Meta Ads", "SEO ve GEO", "Ajanslar için"]','{"cta": "Ücretsiz dene", "demo_url": "https://panel.tanitio.com/demo", "features": ["Instagram, Facebook, LinkedIn, X ve Telegram için zamanlanmış paylaşım ve görsel içerik takvimi", "Markanızın dilinde yapay zekâ içerik stüdyosu: tek tıkla 10 parçalık içerik paketi (başlık, açıklama, CTA, reklam metni, video senaryosu)", "Ham videodan otomatik dikey Reels kurgusu: altyazı, kapak karesi, orijinali bozmayan sürümler", "Google Ads ve Meta Ads yönetimi: taslak → deneme → onay → uygulama zinciri; otomatik optimizasyon varsayılan kapalı ve geri alınabilir", "Yapay zekâ reklam analisti ve 0–100 kreatif puanlaması", "GA4, Search Console, Tag Manager, Merchant Center ve Meta Pixel/CAPI kontrolleri tek ekranda", "30+ site sağlığı kontrolü, Lighthouse/CrUX ve yapay zekâ aramalarında görünürlük (GEO, llms.txt)", "Rakip keşfi (arama sonuçları ve Meta Reklam Kütüphanesi) ve strateji raporu", "Ekip onayları, günlük iş listesi, müşteri izleme portalı ve PDF/CSV dönem raporları"], "pricing_url": "https://tanitio.com/fiyatlandirma"}','Tanitio — Yapay Zekâ Destekli Pazarlama Platformu | GZL Teknoloji','Sosyal medya, reklam, ölçümleme ve ekip onayı tek panelde. Yapay zekâ önerir, karar sizde kalır. 14 gün ücretsiz deneyin.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('30000000-0000-4000-8000-000000000202','en','Tanitio — AI-Assisted Marketing Operations Hub','tanitio','Tanitio is a multi-tenant marketing platform that schedules your Instagram, Facebook, LinkedIn, X and Telegram posts from one calendar, writes content in your brand voice and runs your Google and Meta ads through an approval flow. Built for businesses, agencies and creators. 14-day free trial; the Starter plan is ₺990 per month plus VAT.','Tanitio — AI-Assisted Marketing Operations Hub','["Social Media", "AI Content", "Google Ads", "Meta Ads", "SEO & GEO", "For Agencies"]','{"cta": "Start free trial", "demo_url": "https://panel.tanitio.com/demo", "features": ["Scheduled publishing and a visual content calendar for Instagram, Facebook, LinkedIn, X and Telegram", "AI content studio in your brand voice: a 10-piece content pack in one click (title, caption, CTA, ad copy, video script)", "Automatic vertical Reels editing from raw video: subtitles, cover frame, versions that never overwrite the original", "Google Ads and Meta Ads management: draft → dry run → approval → apply; autonomous optimisation is off by default and reversible", "AI ad analyst and creative scoring from 0 to 100", "GA4, Search Console, Tag Manager, Merchant Center and Meta Pixel/CAPI checks on one screen", "30+ site health checks, Lighthouse/CrUX and visibility in AI search (GEO, llms.txt)", "Competitor discovery (search results and Meta Ad Library) with a strategy report", "Team approvals, a daily task list, a client viewer portal and PDF/CSV period reports"], "pricing_url": "https://tanitio.com/fiyatlandirma"}','Tanitio — AI-Assisted Marketing Platform | GZL Technology','Social media, ads, measurement and team approvals in one panel. AI suggests, you decide. Try it free for 14 days.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('30000000-0000-4000-8000-000000000202','de','Tanitio — KI-gestützte Zentrale für Marketing-Operations','tanitio','Tanitio ist eine mandantenfähige Marketingplattform: Sie plant Beiträge für Instagram, Facebook, LinkedIn, X und Telegram in einem Kalender, erstellt Inhalte in Ihrer Markensprache und steuert Google- und Meta-Anzeigen über einen Freigabeprozess. Für Unternehmen, Agenturen und Creator. 14 Tage kostenlos testen; der Starter-Tarif kostet 990 ₺ pro Monat zzgl. MwSt.','Tanitio — KI-gestützte Zentrale für Marketing-Operations','["Social Media", "KI-Inhalte", "Google Ads", "Meta Ads", "SEO & GEO", "Für Agenturen"]','{"cta": "Kostenlos testen", "demo_url": "https://panel.tanitio.com/demo", "features": ["Geplante Veröffentlichung und visueller Redaktionskalender für Instagram, Facebook, LinkedIn, X und Telegram", "KI-Content-Studio in Ihrer Markensprache: ein 10-teiliges Content-Paket per Klick (Titel, Text, CTA, Anzeigentext, Videoskript)", "Automatischer Hochformat-Reels-Schnitt aus Rohvideo: Untertitel, Titelbild, Versionen ohne Überschreiben des Originals", "Google-Ads- und Meta-Ads-Verwaltung: Entwurf → Testlauf → Freigabe → Umsetzung; autonome Optimierung standardmäßig aus und umkehrbar", "KI-Anzeigenanalyst und Kreativ-Bewertung von 0 bis 100", "GA4-, Search-Console-, Tag-Manager-, Merchant-Center- und Meta-Pixel/CAPI-Prüfungen auf einem Bildschirm", "Über 30 Website-Checks, Lighthouse/CrUX und Sichtbarkeit in KI-Suchen (GEO, llms.txt)", "Wettbewerbsanalyse (Suchergebnisse und Meta-Werbebibliothek) mit Strategiebericht", "Team-Freigaben, tägliche Aufgabenliste, Kundenportal und PDF/CSV-Periodenberichte"], "pricing_url": "https://tanitio.com/fiyatlandirma"}','Tanitio — KI-gestützte Marketingplattform | GZL Technologie','Social Media, Anzeigen, Messung und Team-Freigaben in einem Panel. Die KI schlägt vor, Sie entscheiden. 14 Tage kostenlos testen.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `products` (`id`,`item_type`,`product_kind`,`demo_url`,`docs_url`,`status`,`pricing_model`,`category_id`,`sub_category_id`,`price`,`image_url`,`images`,`is_active`,`is_featured`,`order_num`,`product_code`,`created_at`,`updated_at`) VALUES ('691124b8-e358-57b0-bb30-b35af2638d59','product','saas','https://teklifrota.com/login?demo=1','https://teklifrota.com/pricing','live','subscription','30000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000101',0,'/uploads/products/teklifrota-1600x900.webp','["/uploads/products/teklifrota-1600x900.webp"]',1,1,2,'TEKLIFROTA',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `demo_url`=VALUES(`demo_url`),`docs_url`=VALUES(`docs_url`),`status`=VALUES(`status`),`pricing_model`=VALUES(`pricing_model`),`image_url`=VALUES(`image_url`),`images`=VALUES(`images`),`is_active`=1,`is_featured`=VALUES(`is_featured`),`order_num`=VALUES(`order_num`),`product_code`=VALUES(`product_code`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('691124b8-e358-57b0-bb30-b35af2638d59','tr','TeklifRota — İhracat Teklifi, Evrak ve Navlun Yönetimi','teklifrota','TeklifRota, ihracat yapan üreticilerin alıcı bulma, teklif, proforma, çeki listesi ve navlun süreçlerini tek, denetlenebilir akışta yöneten çok kiracılı B2B platformudur. Elektronik tablolarda dağılan teklifler biter; her revizyon ve onay kayıt altında kalır. 14 gün ücretsiz deneme; Starter paketi aylık 29 $.','TeklifRota — İhracat Teklifi, Evrak ve Navlun Yönetimi','["İhracat", "Teklif ve Proforma", "Navlun", "Gümrük Verisi", "İhracat CRM"]','{"cta": "Ücretsiz dene", "demo_url": "https://teklifrota.com/login?demo=1", "features": ["19,5 milyon+ gümrük kaydında firma ve GTİP ile alıcı arama (Türkiye, ABD, Rusya, Ukrayna)", "Arama sonucunu tek adımda müşteri adayı olarak CRM''e aktarma", "Revizyon geçmişi ve müşteri onayıyla teklif hazırlama", "5 belge türü: teklif, proforma, ticari fatura, çeki listesi, yükleme talimatı — Türkçe, İngilizce, Almanca", "Belge setini tek bağlantı, PDF veya ZIP olarak e-posta, WhatsApp ya da QR ile paylaşma", "TL, USD, EUR ve GBP ile dönüşümsüz çalışma", "Açıklanabilir navlun: 92 açık parametreyle tekrarlanabilir hesap; karayolu, deniz ve havayolu aynı yükte karşılaştırma", "51 ülkenin resmî tatil takvimi", "Rol ve yetkiler, değişiklik geçmişi, firma bazında ayrılmış veri"], "pricing_url": "https://teklifrota.com/pricing"}','TeklifRota — İhracat Teklifi ve Navlun Yönetimi | GZL Teknoloji','İhracatta alıcıdan sevkiyata tek rota: alıcıyı bul, teklifi ver, evrakı hazırla, navlunu kanıtla.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('691124b8-e358-57b0-bb30-b35af2638d59','en','TeklifRota — Export Quotes, Documents and Freight','teklifrota','TeklifRota is a multi-tenant B2B platform where exporting manufacturers run buyer search, quotes, proforma invoices, packing lists and freight in one auditable flow. No more quotes scattered across spreadsheets: every revision and approval is on record. 14-day free trial; the Starter plan is $29 per month.','TeklifRota — Export Quotes, Documents and Freight','["Export", "Quotes & Proforma", "Freight", "Customs Data", "Export CRM"]','{"cta": "Start free trial", "demo_url": "https://teklifrota.com/login?demo=1", "features": ["Buyer search by company or HS code across 19.5M+ customs records (Türkiye, USA, Russia, Ukraine)", "Move a search result into the CRM as a lead in one step", "Quotes with revision history and customer approval", "5 document types: quote, proforma, commercial invoice, packing list, loading instruction — in Turkish, English and German", "Share the document set as one link, PDF or ZIP via email, WhatsApp or QR code", "TRY, USD, EUR and GBP without conversion", "Explainable freight: a reproducible calculation with 92 disclosed parameters; road, sea and air compared on the same load", "Public holiday calendars for 51 countries", "Roles and permissions, change history, data isolated per company"], "pricing_url": "https://teklifrota.com/pricing"}','TeklifRota — Export Quotes and Freight Management | GZL Technology','One route from buyer to shipment: find the buyer, send the quote, prepare the documents, prove the freight.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('691124b8-e358-57b0-bb30-b35af2638d59','de','TeklifRota — Exportangebote, Dokumente und Fracht','teklifrota','TeklifRota ist eine mandantenfähige B2B-Plattform, auf der exportierende Hersteller Käufersuche, Angebote, Proforma-Rechnungen, Packlisten und Fracht in einem nachvollziehbaren Ablauf steuern. Schluss mit verstreuten Tabellen: Jede Revision und Freigabe ist dokumentiert. 14 Tage kostenlos testen; der Starter-Tarif kostet 29 $ pro Monat.','TeklifRota — Exportangebote, Dokumente und Fracht','["Export", "Angebote & Proforma", "Fracht", "Zolldaten", "Export-CRM"]','{"cta": "Kostenlos testen", "demo_url": "https://teklifrota.com/login?demo=1", "features": ["Käufersuche nach Firma oder Zolltarifnummer in über 19,5 Mio. Zolldatensätzen (Türkei, USA, Russland, Ukraine)", "Suchergebnis mit einem Schritt als Lead ins CRM übernehmen", "Angebote mit Revisionsverlauf und Kundenfreigabe", "5 Dokumenttypen: Angebot, Proforma, Handelsrechnung, Packliste, Verladeanweisung — auf Türkisch, Englisch und Deutsch", "Dokumentensatz als Link, PDF oder ZIP per E-Mail, WhatsApp oder QR-Code teilen", "TRY, USD, EUR und GBP ohne Umrechnung", "Nachvollziehbare Frachtkalkulation mit 92 offengelegten Parametern; Straße, See und Luft für dieselbe Ladung im Vergleich", "Feiertagskalender für 51 Länder", "Rollen und Berechtigungen, Änderungsverlauf, nach Firma getrennte Daten"], "pricing_url": "https://teklifrota.com/pricing"}','TeklifRota — Exportangebote und Frachtmanagement | GZL Technologie','Eine Route vom Käufer bis zum Versand: Käufer finden, Angebot senden, Dokumente erstellen, Fracht belegen.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `products` (`id`,`item_type`,`product_kind`,`demo_url`,`docs_url`,`status`,`pricing_model`,`category_id`,`sub_category_id`,`price`,`image_url`,`images`,`is_active`,`is_featured`,`order_num`,`product_code`,`created_at`,`updated_at`) VALUES ('3f1a4a84-c3cb-5640-836c-f02d5c477176','product','saas',NULL,NULL,'live','one_time','30000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000101',0,'/uploads/products/erp-1600x900.webp','["/uploads/products/erp-1600x900.webp"]',1,1,3,'ERP',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `demo_url`=VALUES(`demo_url`),`docs_url`=VALUES(`docs_url`),`status`=VALUES(`status`),`pricing_model`=VALUES(`pricing_model`),`image_url`=VALUES(`image_url`),`images`=VALUES(`images`),`is_active`=1,`is_featured`=VALUES(`is_featured`),`order_num`=VALUES(`order_num`),`product_code`=VALUES(`product_code`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('3f1a4a84-c3cb-5640-836c-f02d5c477176','tr','Firmaya Özel ERP — Üretim, Stok, Sipariş ve İnsan Kaynakları','firmaya-ozel-erp','Kimlik doğrulama, çok kiracılı yapı, rol ve bölüm bazlı yetkiler, iş kuyruğu, insan kaynakları, performans ve prim, denetim kaydı ile bildirim ve dosya yönetimi çekirdekte hazır gelir. Talep, teklif, üretim, stok ve sipariş bölümleri firmanızın gerçek akışına göre yazılır; Excel''deki mevcut verileriniz sisteme taşınır. Üretim, stok, sipariş ve müşteri yönetimini canlıda yürüten referans sistemlerimiz var. Kapsama göre teklif hazırlanır.','Firmaya Özel ERP — Üretim, Stok, Sipariş ve İnsan Kaynakları','["ERP", "Üretim", "Stok", "Sipariş", "İnsan Kaynakları", "Özel Yazılım"]','{"cta": "Teklif al", "demo_url": null, "features": ["Rol × bölüm yetki matrisi: kim neyi görür, kim neyi değiştirir", "Kokpit: herkesin önüne kendi iş kuyruğu gelir", "Üretim, stok, sipariş ve teklif bölümleri sizin sürecinize göre", "İnsan kaynakları, performans ve prim takibi", "Her değişikliğin denetim kaydı: kim, ne zaman, neyi değiştirdi", "Bildirimler ve dosya yönetimi", "Çok kiracılı yapı: birden çok firma ya da şube aynı sistemde, verileri ayrı", "Excel''deki mevcut verilerin sisteme taşınması", "Logo, ad ve tema verinizden gelir; sistem sizin markanızla açılır"]}','Firmaya Özel ERP Yazılımı — Üretim, Stok, Sipariş | GZL Teknoloji','Hazır ve çalışan bir çekirdek üzerine, sizin iş akışınıza göre kurulan ERP. Paket yazılıma uymak yerine yazılım size uyar.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('3f1a4a84-c3cb-5640-836c-f02d5c477176','en','Custom ERP — Production, Stock, Orders and HR','custom-erp','Authentication, a multi-tenant structure, role- and section-based permissions, a work queue, HR, performance and bonus tracking, an audit trail, notifications and file management come ready in the core. Request, quote, production, stock and order sections are written around your real process, and your existing Excel data is migrated. We run reference systems in production that manage production, stock, orders and customers. Pricing is quoted by scope.','Custom ERP — Production, Stock, Orders and HR','["ERP", "Production", "Inventory", "Orders", "HR", "Custom Software"]','{"cta": "Request a quote", "demo_url": null, "features": ["Role × section permission matrix: who sees and who changes what", "Cockpit: everyone gets their own work queue", "Production, stock, order and quote sections shaped to your process", "HR, performance and bonus tracking", "Audit trail for every change: who changed what, and when", "Notifications and file management", "Multi-tenant: several companies or branches in one system with separated data", "Migration of your existing Excel data", "Logo, name and theme come from your data; the system opens with your brand"]}','Custom ERP Software — Production, Stock, Orders | GZL Technology','An ERP built on a proven, working core and shaped around your workflow. Instead of bending to packaged software, the software fits you.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('3f1a4a84-c3cb-5640-836c-f02d5c477176','de','Individuelles ERP — Produktion, Lager, Aufträge und Personal','individuelles-erp','Authentifizierung, Mandantenfähigkeit, rollen- und bereichsbasierte Rechte, Arbeitswarteschlange, Personalwesen, Leistungs- und Prämienverwaltung, Audit-Trail sowie Benachrichtigungen und Dateiverwaltung sind im Kern fertig. Anfrage-, Angebots-, Produktions-, Lager- und Auftragsbereiche werden nach Ihrem tatsächlichen Ablauf entwickelt; vorhandene Excel-Daten werden übernommen. Referenzsysteme für Produktion, Lager, Aufträge und Kunden laufen bereits produktiv. Das Angebot richtet sich nach dem Umfang.','Individuelles ERP — Produktion, Lager, Aufträge und Personal','["ERP", "Produktion", "Lager", "Aufträge", "Personal", "Individualsoftware"]','{"cta": "Angebot anfordern", "demo_url": null, "features": ["Rollen × Bereiche-Rechtematrix: wer was sieht und wer was ändert", "Cockpit: jede Person sieht ihre eigene Arbeitswarteschlange", "Produktions-, Lager-, Auftrags- und Angebotsbereiche nach Ihrem Prozess", "Personalwesen, Leistungs- und Prämienverwaltung", "Audit-Trail für jede Änderung: wer hat was wann geändert", "Benachrichtigungen und Dateiverwaltung", "Mandantenfähig: mehrere Firmen oder Filialen in einem System mit getrennten Daten", "Übernahme Ihrer vorhandenen Excel-Daten", "Logo, Name und Design kommen aus Ihren Daten; das System startet mit Ihrer Marke"]}','Individuelle ERP-Software — Produktion, Lager, Aufträge | GZL Technologie','Ein ERP auf einem bewährten, laufenden Kern — zugeschnitten auf Ihre Abläufe. Statt sich an Standardsoftware anzupassen, passt sich die Software Ihnen an.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
