INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('b3ccb432-a68c-5918-abe5-ad35a57eadf8','tr','Satış ve Müşteri Yönetimi (CRM) — Firmaya Özel','firmaya-ozel-crm','Müşteri kartları, görüşme kayıtları ve fırsat hattı; tekliften revizyona, PDF''ten siparişe uzanan zincir; görevler, otomasyonlar ve her adımın denetim kaydı. CRM, ERP çekirdeğimizle aynı altyapıda çalışır ve gerektiğinde sipariş, üretim, sevkiyat ve stokla bütünleşir. İhracat yapan ekipler için TeklifRota''daki hazır ihracat CRM''i de kullanılabilir. Kapsama göre teklif hazırlanır.','Satış ve Müşteri Yönetimi (CRM) — Firmaya Özel','["CRM", "Satış Hattı", "Teklif", "Müşteri Yönetimi", "Özel Yazılım"]','{"cta": "Teklif al", "demo_url": null, "features": ["Müşteri ve iletişim kartları", "Görüşme ve toplantı kayıtları", "Fırsat hattı (pipeline) ile satış aşamalarını izleme", "Teklif → revizyon → PDF → sipariş zinciri", "Görev, hatırlatma ve otomasyonlar", "Rol bazlı yetkiler ve her adımın denetim kaydı", "Sipariş, üretim, sevkiyat ve stokla ERP entegrasyonu", "İhracat ekipleri için TeklifRota ile hazır ihracat CRM''i"]}','Firmaya Özel CRM — Satış ve Müşteri Yönetimi | GZL Teknoloji','Müşteri, görüşme ve fırsat takibinden teklif ve siparişe kadar satış sürecinizi tek akışta yönetin.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('b3ccb432-a68c-5918-abe5-ad35a57eadf8','en','Sales and Customer Management (CRM) — Built for You','custom-crm','Customer cards, meeting logs and an opportunity pipeline; a chain from quote to revision, PDF and order; tasks, automations and an audit trail for every step. The CRM runs on the same foundation as our ERP core and connects to orders, production, shipping and stock when needed. Export teams can also use the ready-made export CRM in TeklifRota. Pricing is quoted by scope.','Sales and Customer Management (CRM) — Built for You','["CRM", "Sales Pipeline", "Quotes", "Customer Management", "Custom Software"]','{"cta": "Request a quote", "demo_url": null, "features": ["Customer and contact cards", "Meeting and call logs", "Opportunity pipeline to track sales stages", "Quote → revision → PDF → order chain", "Tasks, reminders and automations", "Role-based permissions and an audit trail for every step", "ERP integration with orders, production, shipping and stock", "Ready-made export CRM for export teams with TeklifRota"]}','Custom CRM — Sales and Customer Management | GZL Technology','Run your sales process in one flow, from customers, meetings and opportunities to quotes and orders.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('b3ccb432-a68c-5918-abe5-ad35a57eadf8','de','Vertrieb und Kundenmanagement (CRM) — individuell','individuelles-crm','Kundenkarten, Gesprächsprotokolle und eine Verkaufspipeline; eine Kette vom Angebot über Revision und PDF bis zum Auftrag; Aufgaben, Automatisierungen und ein Audit-Trail für jeden Schritt. Das CRM läuft auf derselben Basis wie unser ERP-Kern und verbindet sich bei Bedarf mit Aufträgen, Produktion, Versand und Lager. Exportteams können zudem das fertige Export-CRM in TeklifRota nutzen. Das Angebot richtet sich nach dem Umfang.','Vertrieb und Kundenmanagement (CRM) — individuell','["CRM", "Vertriebspipeline", "Angebote", "Kundenmanagement", "Individualsoftware"]','{"cta": "Angebot anfordern", "demo_url": null, "features": ["Kunden- und Kontaktkarten", "Gesprächs- und Terminprotokolle", "Verkaufspipeline zur Verfolgung der Phasen", "Kette Angebot → Revision → PDF → Auftrag", "Aufgaben, Erinnerungen und Automatisierungen", "Rollenbasierte Rechte und Audit-Trail für jeden Schritt", "ERP-Anbindung an Aufträge, Produktion, Versand und Lager", "Fertiges Export-CRM für Exportteams mit TeklifRota"]}','Individuelles CRM — Vertrieb und Kundenmanagement | GZL Technologie','Steuern Sie Ihren Vertrieb in einem Ablauf: von Kunden, Gesprächen und Chancen bis zu Angeboten und Aufträgen.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `products` (`id`,`item_type`,`product_kind`,`demo_url`,`docs_url`,`status`,`pricing_model`,`category_id`,`sub_category_id`,`price`,`image_url`,`images`,`is_active`,`is_featured`,`order_num`,`product_code`,`created_at`,`updated_at`) VALUES ('8c556f80-ca9e-5729-9929-bf12a9b1ffca','product','saas',NULL,NULL,'live','one_time','30000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000101',0,'/uploads/products/osgb-1600x900.webp','["/uploads/products/osgb-1600x900.webp"]',1,1,5,'OSGB',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `demo_url`=VALUES(`demo_url`),`docs_url`=VALUES(`docs_url`),`status`=VALUES(`status`),`pricing_model`=VALUES(`pricing_model`),`image_url`=VALUES(`image_url`),`images`=VALUES(`images`),`is_active`=1,`is_featured`=VALUES(`is_featured`),`order_num`=VALUES(`order_num`),`product_code`=VALUES(`product_code`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('8c556f80-ca9e-5729-9929-bf12a9b1ffca','tr','OSGB İşletme Yönetim Sistemi — İSG Operasyonu Tek Panelde','osgb-isletme-yonetim-sistemi','Ortak sağlık güvenlik birimleri mevzuat gereği yüzlerce işyerine İSG uzmanı ve işyeri hekimi hizmeti verir; bu operasyon çoğunlukla dağınık Excel dosyalarıyla yürür. OSGB İşletme Yönetim Sistemi firma kartlarından ziyaret planına, sağlık taramasından süreli evraka, tekliften tahsilata kadar tüm işi tek panele taşır. Canlıda çalışan bir OSGB sistemi temel alınır, sizin iş akışınıza göre kurulur ve mevcut Excel/İSG-KATİP verileriniz aktarılır. Kapsama göre teklif hazırlanır.','OSGB İşletme Yönetim Sistemi — İSG Operasyonu Tek Panelde','["OSGB", "İSG", "İşyeri Hekimi", "Ziyaret Planlama", "Evrak Takibi", "Özel Yazılım"]','{"cta": "Teklif al", "demo_url": null, "features": ["Firma kartları, sözleşme ve tehlike sınıfı kayıtları", "İSG-KATİP sözleşme dökümüyle atama mutabakatı", "Mevzuata göre ziyaret planı, uzman ve işyeri hekimi ataması", "Kanıtla kapanan ziyaret kaydı ve görev yönetimi", "Sağlık raporu, tarama takibi ve hekim ekranı", "Evrak arşivi ve süresi dolacak belgeler için uyarı", "Teklif, satış, tahsilat ve finans takibi", "İK/personel yönetimi ve rol tabanlı yetkiler", "Bildirim ve otomasyon altyapısı"]}','OSGB İşletme Yönetim Sistemi — İSG Yazılımı | GZL Teknoloji','Sözleşme, ziyaret planı, uzman ve hekim ataması, sağlık taraması, evrak ve tahsilatı Excel yerine tek panelde yönetin.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('8c556f80-ca9e-5729-9929-bf12a9b1ffca','en','OSGB Management System — Occupational Health & Safety Operations in One Panel','osgb-management-system','Joint health and safety units (OSGB) in Türkiye provide safety experts and workplace physicians to hundreds of workplaces by law, and this work usually runs on scattered Excel files. The OSGB Management System brings everything into one panel, from company records and visit plans to health screening, time-limited documents, quotes and collections. It builds on an OSGB system already running in production, is set up around your workflow, and your existing Excel and İSG-KATİP data is migrated. Pricing is quoted by scope.','OSGB Management System — Occupational Health & Safety Operations in One Panel','["OSGB", "Occupational Health & Safety", "Workplace Physician", "Visit Planning", "Document Tracking", "Custom Software"]','{"cta": "Request a quote", "demo_url": null, "features": ["Company records, contracts and hazard classes", "Assignment reconciliation with İSG-KATİP contract exports", "Regulation-based visit planning with safety expert and physician assignment", "Visit records closed with evidence, plus task management", "Health reports, screening tracking and a physician view", "Document archive with alerts for expiring documents", "Quotes, sales, collections and finance tracking", "HR/staff management and role-based permissions", "Notification and automation infrastructure"]}','OSGB Management System — OHS Software | GZL Technology','Manage contracts, visit plans, safety expert and physician assignments, health screening, documents and collections in one panel instead of Excel.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
INSERT INTO `product_i18n` (`product_id`,`locale`,`title`,`slug`,`description`,`alt`,`tags`,`specifications`,`meta_title`,`meta_description`,`created_at`,`updated_at`) VALUES ('8c556f80-ca9e-5729-9929-bf12a9b1ffca','de','OSGB-Managementsystem — Arbeitsschutz-Operations in einem Panel','osgb-managementsystem','Gemeinsame Arbeitsschutzeinheiten (OSGB) in der Türkei stellen gesetzlich vorgeschriebene Fachkräfte für Arbeitssicherheit und Betriebsärzte für Hunderte Betriebe; meist läuft das über verstreute Excel-Dateien. Das OSGB-Managementsystem bündelt alles in einem Panel: von Firmenakten und Besuchsplänen über Gesundheitsuntersuchungen und befristete Dokumente bis zu Angeboten und Zahlungseingängen. Grundlage ist ein produktiv laufendes OSGB-System; es wird an Ihre Abläufe angepasst, vorhandene Excel- und İSG-KATİP-Daten werden übernommen. Das Angebot richtet sich nach dem Umfang.','OSGB-Managementsystem — Arbeitsschutz-Operations in einem Panel','["OSGB", "Arbeitsschutz", "Betriebsarzt", "Besuchsplanung", "Dokumentenverwaltung", "Individualsoftware"]','{"cta": "Angebot anfordern", "demo_url": null, "features": ["Firmenakten, Verträge und Gefahrenklassen", "Abgleich der Zuweisungen mit İSG-KATİP-Vertragsexporten", "Vorschriftsgemäße Besuchsplanung mit Zuweisung von Fachkräften und Betriebsärzten", "Besuchsnachweise mit Beleg und Aufgabenverwaltung", "Gesundheitsberichte, Untersuchungsverfolgung und Arztansicht", "Dokumentenarchiv mit Warnung vor ablaufenden Unterlagen", "Angebote, Vertrieb, Zahlungseingänge und Finanzen", "Personalverwaltung und rollenbasierte Rechte", "Benachrichtigungs- und Automatisierungsinfrastruktur"]}','OSGB-Managementsystem — Arbeitsschutz-Software | GZL Technologie','Verträge, Besuchsplanung, Zuweisung von Fachkräften und Betriebsärzten, Gesundheitsuntersuchungen, Dokumente und Inkasso in einem Panel statt in Excel.',NOW(3),NOW(3)) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`slug`=VALUES(`slug`),`description`=VALUES(`description`),`alt`=VALUES(`alt`),`tags`=VALUES(`tags`),`specifications`=VALUES(`specifications`),`meta_title`=VALUES(`meta_title`),`meta_description`=VALUES(`meta_description`),`updated_at`=NOW(3);
