-- Mevcut urunler: sira, gorunurluk, calisan demo adresi.
UPDATE `products` SET `order_num`=92, `is_active`=0, `is_featured`=IF(0=1, `is_featured`, 0), `demo_url`='https://ihracatradari.com.tr', `updated_at`=NOW(3) WHERE `product_code`='IHRACAT-RADARI';
UPDATE `product_i18n` SET `specifications`=JSON_SET(COALESCE(`specifications`,'{}'),'$.demo_url','https://ihracatradari.com.tr'), `updated_at`=NOW(3) WHERE `product_id`=(SELECT `id` FROM `products` WHERE `product_code`='IHRACAT-RADARI' LIMIT 1);
UPDATE `products` SET `order_num`=6, `is_active`=1, `is_featured`=IF(1=1, `is_featured`, 0), `demo_url`='https://scraper.guezelwebdesign.com/docs', `updated_at`=NOW(3) WHERE `product_code`='SCRAPER-API';
UPDATE `product_i18n` SET `specifications`=JSON_SET(COALESCE(`specifications`,'{}'),'$.demo_url','https://scraper.guezelwebdesign.com/docs'), `updated_at`=NOW(3) WHERE `product_id`=(SELECT `id` FROM `products` WHERE `product_code`='SCRAPER-API' LIMIT 1);
UPDATE `products` SET `order_num`=90, `is_active`=0, `is_featured`=IF(0=1, `is_featured`, 0), `updated_at`=NOW(3) WHERE `product_code`='GEOSERRA';
UPDATE `products` SET `order_num`=91, `is_active`=0, `is_featured`=IF(0=1, `is_featured`, 0), `updated_at`=NOW(3) WHERE `product_code`='KATALOGAI';

-- Hizmet karti: OSGB gorseli musteri sitesinin ekraniydi (gosterim izni yok) -> uretilmis grafik.
UPDATE `services` s JOIN (SELECT `service_id` FROM `services_i18n` WHERE `locale`='tr' AND `slug`='osgb-isletme-yonetim-sistemi' LIMIT 1) x ON s.`id`=x.`service_id` SET s.`featured_image`='/uploads/services/osgb-isletme-yonetim-sistemi/osgb-grafik-1600x900.webp', s.`image_url`='/uploads/services/osgb-isletme-yonetim-sistemi/osgb-grafik-1600x900.webp', s.`image_asset_id`=NULL, s.`updated_at`=NOW(3);
UPDATE `service_images` si JOIN (SELECT `service_id` FROM `services_i18n` WHERE `locale`='tr' AND `slug`='osgb-isletme-yonetim-sistemi' LIMIT 1) x ON si.`service_id`=x.`service_id` SET si.`image_url`='/uploads/services/osgb-isletme-yonetim-sistemi/osgb-grafik-1600x900.webp', si.`image_asset_id`=NULL, si.`updated_at`=NOW(3);
COMMIT;
